update public.programming_projects set title='مشروع تطبيقي: محلل بيانات تعليمية تجريبية',brief='ابنِ محللًا لملف بيانات تعليمي اصطناعي يقرأ الدرجات، يتحقق من القيم، يحسب المؤشرات، ويعرض ملخصًا بصريًا مع توضيح حدود الاستنتاجات وحماية الخصوصية.',requirements='["أنشئ ملف CSV ببيانات اصطناعية فقط، يحتوي student_code وsubject وscore وterm، ولا تستخدم أسماء أو بيانات طلاب حقيقية.","اقرأ الملف وتحقق من وجود الأعمدة المطلوبة، ومن أن score رقم يقع في المجال من 0 إلى 100.","تعامل مع الصفوف الناقصة أو غير الصالحة بقاعدة موثقة: ارفضها أو استبعدها مع عدّها في تقرير جودة البيانات.","احسب المتوسط وأعلى وأقل درجة وعدد السجلات لكل مادة، ثم اعرض النتائج في جدول واضح.","أنشئ رسمًا واحدًا مناسبًا للمقارنة بين المواد، مع عنوان وتسميات ومحاور مفهومة.","أضف مقارنة بسيطة بين فصلين اصطناعيين، واشرح أن الارتباط أو التحسن العددي لا يثبت سببًا معينًا.","اختبر ملفًا صحيحًا وملفًا فارغًا وصفًا بقيمة غير صالحة، وأظهر رسالة خطأ مفهومة بدل توقف غير مفسر.","اكتب README يوضح مصدر البيانات الاصطناعية وطريقة التشغيل والنتائج والقيود وما لن يستنتجه المشروع."]'::jsonb,rubric='[{"weight":20,"criterion":"جودة البيانات والتحقق","description":"قراءة CSV والتحقق من الأعمدة والأنواع والقيم والصفوف غير الصالحة."},{"weight":20,"criterion":"صحة التحليل","description":"حساب المؤشرات وتجميع النتائج دون أخطاء."},{"weight":15,"criterion":"التصور والعرض","description":"رسم واضح بعناوين وتسميات مناسبة."},{"weight":15,"criterion":"الاختبارات","description":"اختبار الحالات العادية والفارغة والحدّية."},{"weight":15,"criterion":"المسؤولية والخصوصية","description":"استخدام بيانات اصطناعية وشرح حدود الاستنتاج."},{"weight":15,"criterion":"التوثيق والتنظيم","description":"ملفات مرتبة وREADME قابل للتنفيذ."}]'::jsonb,estimated_hours=4,difficulty='intermediate' where id='4d61729d-022c-43fa-8942-3b24419a3973' and is_published=true;
update public.programming_projects set title='مشروع تطبيقي: مدير مخزون بلغة برمجة',brief='أنشئ برنامجًا نصيًا لإدارة مخزون صغير باستخدام Python أو C++، مع إضافة المنتجات وتحديث الكميات والبحث وإصدار ملخص، مع التحقق من المدخلات.',requirements='["اختر Python أو C++، واكتب في README سبب اختيار اللغة وطريقة تشغيل البرنامج.","مثّل المنتج بمعرّف فريد واسم وسعر وكمية، واستخدم بنية بيانات مناسبة لتخزين مجموعة المنتجات.","نفّذ إضافة منتج، وعرض المنتجات، والبحث بالمعرّف، وتحديث الكمية، مع منع المعرّفات المكررة.","تحقق من أن السعر والكمية قيم غير سالبة، وأن الكمية المدخلة عدد صحيح مناسب.","احسب قيمة المخزون الإجمالية، واعرض تقريرًا مرتبًا حسب المعرّف أو الاسم.","تعامل مع منتج غير موجود ومدخل فارغ وقائمة مخزون فارغة برسائل مفهومة.","اكتب اختبارات أو حالات تشغيل موثقة تشمل إضافة وتحديث وبحثًا ناجحًا وفاشلًا.","قسّم البرنامج إلى دوال أو وحدات صغيرة، واستخدم أسماء واضحة وتعليقات تشرح القرارات غير البديهية."]'::jsonb,rubric='[{"weight":25,"criterion":"الوظائف الأساسية","description":"الإضافة والعرض والبحث والتحديث والتقرير تعمل."},{"weight":20,"criterion":"هياكل البيانات والتصميم","description":"اختيار بنية مناسبة وتقسيم البرنامج إلى وحدات."},{"weight":20,"criterion":"التحقق ومعالجة الحالات","description":"رفض القيم غير الصالحة ومعالجة السجلات غير الموجودة."},{"weight":15,"criterion":"الاختبارات","description":"حالات صحيحة وحدّية وفارغة موثقة."},{"weight":10,"criterion":"جودة الكود","description":"وضوح الأسماء والتنظيم وسهولة القراءة."},{"weight":10,"criterion":"التوثيق","description":"README يشرح اللغة والتشغيل والميزات."}]'::jsonb,estimated_hours=5,difficulty='intermediate' where id='5aa1b97b-5633-4c17-83d5-1609daf64f03' and is_published=true;
update public.programming_projects set title='مشروع تطبيقي: مخطط رحلة حل المشكلة',brief='حوّل مشكلة يومية إلى خوارزمية قابلة للتنفيذ: حلّل المدخلات، صمم خطوات الحل، اختبر الحالات، ثم نفّذ برنامجًا صغيرًا يعرض خطة منظمة.',requirements='["اختر مشكلة تعليمية بسيطة مثل ترتيب مهام أسبوعية باستخدام بيانات تجريبية، وحدد المستخدم والهدف والقيود.","اكتب المدخلات والمخرجات بوضوح، وحدد القواعد التي يجب ألا يخالفها الحل.","اكتب Pseudocode يشرح الخوارزمية قبل اختيار لغة البرمجة.","ارسم Flowchart يوضح البداية والمدخلات والقرارات والتكرار والنهاية.","نفّذ الحل باستخدام قائمة أو مصفوفة، وشرط، وحلقة، ودالة واحدة على الأقل.","اشرح التعقيد بصورة مبسطة: ما الذي يحدث إذا تضاعف عدد العناصر؟ لا تدّعِ قياس أداء لم تختبره.","اختبر قائمة فارغة وعنصرًا واحدًا وعناصر مكررة ومدخلًا غير صالح.","سلّم الخوارزمية والمخطط والكود وجدول الاختبارات وملخصًا لما تعلمته."]'::jsonb,rubric='[{"weight":20,"criterion":"تحليل المشكلة","description":"تحديد المستخدم والمدخلات والمخرجات والقيود."},{"weight":20,"criterion":"الخوارزمية","description":"خطوات واضحة ومنطقية قبل كتابة الكود."},{"weight":15,"criterion":"المخطط","description":"Flowchart صحيح ومتسق مع الخوارزمية."},{"weight":20,"criterion":"التنفيذ","description":"استخدام مناسب للمتغيرات والشروط والحلقات والدوال."},{"weight":15,"criterion":"الاختبارات","description":"تغطية الحالات العادية والحدّية وغير الصالحة."},{"weight":10,"criterion":"التفسير والتوثيق","description":"شرح القرارات وحدود الحل بوضوح."}]'::jsonb,estimated_hours=3,difficulty='beginner' where id='00ba031a-c1cc-4c54-8dc5-5bcef5b39046' and is_published=true;
update public.programming_projects set title='مشروع تطبيقي: حزمة جودة وإصدار للمشروع',brief='جهّز مستودع مشروع منظمًا وقابلًا للمراجعة: وثّق خطوات التشغيل، أضف اختبارات، راجع التغييرات، وأنشئ قائمة تحقق للإصدار دون تضمين أسرار أو ملفات شخصية.',requirements='["أنشئ مستودعًا تدريبيًا به src وtests وdocs وREADME و.gitignore.","اكتب تعليمات إعداد وتشغيل واضحة، وحدد المتطلبات والإصدارات التي يحتاجها المشروع.","أضف اختبارين آليين على الأقل لوظيفة أساسية، واكتب حالة يدوية لتجربة الواجهة أو المخرجات.","أنشئ فرعًا لميزة صغيرة، واحفظ التغيير في Commit برسالة محددة، ثم اكتب وصف Pull Request.","اكتب Release Checklist تتضمن الاختبارات، والتوثيق، والملفات، والروابط، ومراجعة الإعدادات.","افحص المستودع بحثًا عن ملفات إعداد محلية أو بيانات شخصية أو مفاتيح، واستبعدها دون نشرها.","اكتب سجلًا يوضح مشكلة واحدة اكتشفتها أثناء المراجعة وكيف تحققت من إصلاحها.","سلّم رابط المستودع وREADME ونتائج الاختبارات وقائمة التحقق."]'::jsonb,rubric='[{"weight":20,"criterion":"هيكل المستودع","description":"تنظيم المصدر والاختبارات والتوثيق والملفات المستبعدة."},{"weight":20,"criterion":"الاختبارات","description":"اختبارات قابلة للتكرار ونتائج موثقة."},{"weight":20,"criterion":"Git وسير العمل","description":"فرع وCommit ووصف PR واضح."},{"weight":15,"criterion":"مراجعة الإصدار","description":"قائمة تحقق عملية ومكتملة."},{"weight":15,"criterion":"الأمان","description":"عدم تضمين أسرار أو بيانات خاصة."},{"weight":10,"criterion":"التوثيق","description":"README وسجل التغييرات واضحان."}]'::jsonb,estimated_hours=4,difficulty='intermediate' where id='8f981963-624c-4130-b297-aaf408137a1e' and is_published=true;
update public.programming_projects set title='مشروع تطبيقي: لعبة جمع النجوم في Scratch',brief='صمّم لعبة تعليمية قصيرة في Scratch: شخصية تتحرك داخل مساحة لعب، تجمع عناصرًا، وتحسب النقاط، وتعرض رسالة نهاية، مع قواعد واضحة وتجربة قابلة لإعادة اللعب.',requirements='["حدد فكرة اللعبة والشخصيات والخلفية وقاعدة الفوز في مخطط صغير قبل بناء الكتل.","استخدم أحداث البداية ولوحة المفاتيح لتحريك الشخصية، مع حدود تمنع خروجها من مساحة اللعب.","أنشئ متغير score يبدأ من صفر ويزيد عند لمس عنصر قابل للجمع.","استخدم التكرار والشرط لاكتشاف التلامس وتحديث النقاط بطريقة لا تحتسب العنصر نفسه مرات غير مقصودة.","أضف مؤقتًا أو عددًا محددًا من العناصر، ثم اعرض رسالة نهاية مفهومة.","أضف زر أو حدثًا لإعادة اللعبة إلى الحالة الابتدائية.","اختبر الحركة والتصادم والنقاط وإعادة التشغيل، وسجل خطأ واحدًا وكيف أصلحته.","سلّم رابط المشروع أو ملفه مع وصف الكتل الأساسية وصورة لا تحتوي معلومات شخصية."]'::jsonb,rubric='[{"weight":20,"criterion":"الفكرة والقواعد","description":"هدف اللعبة وشروط الفوز مفهومة."},{"weight":25,"criterion":"التحكم والحركة","description":"الأحداث والحركة وحدود مساحة اللعب تعمل."},{"weight":20,"criterion":"المنطق والنقاط","description":"التصادم والشروط والمتغيرات والتكرار صحيحة."},{"weight":15,"criterion":"إعادة التشغيل","description":"إعادة ضبط الحالة تعمل دون بقايا من الجولة السابقة."},{"weight":10,"criterion":"الاختبار","description":"اختبار الحالات الأساسية وتوثيق إصلاح."},{"weight":10,"criterion":"الشرح","description":"وصف واضح للكتل وآلية اللعب."}]'::jsonb,estimated_hours=3,difficulty='beginner' where id='ecbdc42b-5169-4cd0-8e55-22a1f9a22f65' and is_published=true;
update public.programming_projects set title='مشروع تطبيقي: مدير مهام نصي باستخدام Python',brief='ابنِ تطبيقًا نصيًا لإدارة مهام الدراسة باستخدام الدوال والقوائم والقواميس والتحقق من المدخلات وحفظ البيانات في JSON، مع فصل منطق التطبيق عن واجهة الأوامر.',requirements='["مثّل المهمة بقاموس يحتوي id وtitle وdue_date وcompleted، وخزّن المهام في قائمة.","أنشئ دوال add_task وlist_tasks وcomplete_task وdelete_task وsave_tasks وload_tasks.","تحقق من العنوان غير الفارغ وصيغة التاريخ، ولا تسمح بمعرّف مكرر.","احفظ البيانات في ملف JSON، وتعامل مع غياب الملف أو تلف محتواه برسالة مفهومة دون فقد صامت للبيانات.","اعرض المهام المفتوحة والمكتملة، واسمح بالبحث أو التصفية حسب الحالة.","افصل حلقة القائمة النصية عن دوال إدارة البيانات حتى يسهل اختبار كل دالة.","اكتب اختبارات لحالة إضافة صحيحة ومعرّف غير موجود وعنوان فارغ وملف بيانات غير موجود.","اكتب README يوضح التشغيل ومكان ملف البيانات وحدود النسخة الأولى."]'::jsonb,rubric='[{"weight":25,"criterion":"إدارة المهام","description":"الإضافة والعرض والإكمال والحذف تعمل بصورة صحيحة."},{"weight":20,"criterion":"التخزين والاسترجاع","description":"JSON يُحفظ ويُقرأ مع معالجة الحالات غير المتوقعة."},{"weight":20,"criterion":"التحقق","description":"المدخلات والمعرّفات والتواريخ تتحقق بوضوح."},{"weight":15,"criterion":"التصميم والاختبارات","description":"دوال مستقلة واختبارات للحالات الأساسية والحدّية."},{"weight":10,"criterion":"تجربة الاستخدام","description":"قائمة ورسائل واضحة وسهلة الفهم."},{"weight":10,"criterion":"التوثيق","description":"تعليمات تشغيل وحدود معروفة."}]'::jsonb,estimated_hours=5,difficulty='intermediate' where id='34a3ed54-eb38-4aba-99f5-89f8070e50e6' and is_published=true;
update public.programming_projects set title='مشروع تطبيقي: مخطط مذاكرة على الهاتف باستخدام Flutter',brief='أنشئ تطبيق Flutter محليًا لتنظيم جلسات المذاكرة، يعرض قائمة مهام، ويسمح بإضافة جلسة وتحديدها مكتملة مع واجهة قابلة للاستخدام على أحجام شاشة مختلفة.',requirements='["أنشئ مشروع Flutter منظمًا، وحدد شاشة رئيسية وشاشة أو نموذجًا لإضافة جلسة.","مثّل جلسة المذاكرة بعنوان ومادة ومدة وحالة إنجاز، واستخدم نموذج بيانات واضحًا.","اعرض الجلسات في قائمة، وأضف جلسة جديدة، وغيّر حالتها، واحذف جلسة تجريبية.","تحقق من العنوان والمدة، وارفض القيم الفارغة أو المدة غير المنطقية برسالة واضحة.","استخدم StatefulWidget أو إدارة حالة مناسبة، واشرح أين تحفظ الحالة وكيف تتحدث الواجهة.","طبّق تصميمًا متجاوبًا مع SafeArea وعناصر قابلة للقراءة وأهداف لمس مناسبة.","اختبر القائمة الفارغة والإضافة والتحديث والشاشات الضيقة، واستخدم بيانات تجريبية فقط.","اكتب README يشرح إعداد Flutter وتشغيل التطبيق والميزات التي لم تدخل النسخة الأولى."]'::jsonb,rubric='[{"weight":20,"criterion":"هيكل Flutter","description":"تنظيم الملفات والشاشات والمكونات."},{"weight":25,"criterion":"الوظائف وإدارة الحالة","description":"الإضافة والعرض وتحديث الحالة والحذف."},{"weight":15,"criterion":"التحقق","description":"منع المدخلات غير الصالحة ورسائل واضحة."},{"weight":15,"criterion":"التصميم المتجاوب","description":"تخطيط مناسب للشاشات المختلفة وسهولة لمس."},{"weight":15,"criterion":"الاختبار","description":"اختبار الحالات الفارغة والحدّية والوظائف."},{"weight":10,"criterion":"التوثيق","description":"شرح الإعداد والتشغيل والقيود."}]'::jsonb,estimated_hours=6,difficulty='intermediate' where id='cb969259-142c-48d4-95f4-e3922e82a33d' and is_published=true;
update public.programming_projects set title='مشروع تطبيقي: ملف أعمال رقمي متجاوب',brief='أنشئ موقع Portfolio يعرض مشاريع تعليمية وهمية أو مشاريعك التي تملك حق نشرها، ويشرح دورك والتقنيات والاختبارات، مع تصميم متجاوب وإمكانية وصول جيدة.',requirements='["حدد جمهور الموقع والهدف، وارسم ترتيب الأقسام قبل كتابة HTML.","أنشئ بنية دلالية تحتوي مقدمة ومهارات ومشاريع وطريقة تواصل عامة، دون نشر رقم هاتف أو عنوان شخصي.","استخدم CSS Grid أو Flexbox ومتغيرات CSS لدعم الهاتف والحاسوب واتجاه RTL عند الحاجة.","اعرض بطاقات المشاريع من مصفوفة JavaScript، مع عنوان ووصف وتقنيات ورابط تجريبي أو مستودع.","أضف فلترة بسيطة حسب نوع المشروع، وحالة واضحة عند عدم وجود نتائج.","استخدم روابط وأزرار ذات أسماء مفهومة، وتأكد من التنقل بلوحة المفاتيح وتباين النصوص.","اختبر عرضًا ضيقًا وعريضًا ونصوصًا طويلة وروابط غير متاحة، ولا تضع روابط وهمية توحي بأنها حقيقية.","اكتب README يشرح البنية وطريقة التشغيل وما الذي نفذته بنفسك."]'::jsonb,rubric='[{"weight":20,"criterion":"المحتوى والبنية","description":"أقسام واضحة وهيكل HTML دلالي."},{"weight":20,"criterion":"التصميم المتجاوب","description":"تخطيط جيد على الهاتف والحاسوب."},{"weight":20,"criterion":"التفاعل","description":"عرض البطاقات والفلترة وحالة عدم وجود نتائج."},{"weight":15,"criterion":"إمكانية الوصول","description":"لوحة المفاتيح وأسماء العناصر وتباين النص."},{"weight":15,"criterion":"المصداقية والخصوصية","description":"روابط حقيقية أو موضحة كتجريبية وعدم نشر بيانات خاصة."},{"weight":10,"criterion":"التوثيق","description":"README يشرح التشغيل والمساهمات."}]'::jsonb,estimated_hours=4,difficulty='intermediate' where id='38559801-d85d-4325-9c00-258f1d431385' and is_published=true;
